  "measure_id": "MEAS-5D011247",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Makes assaulting an on-duty hospital worker a felony punishable by up to three years in prison, rather than the current maximum of one year in jail for assault."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C47",
      "effect": "moves",
      "direction": "toward longer sentences and felony classification for specific assaults",
      "quote": "Assault on an on-duty hospital worker is a felony punishable by up to three years in prison.",
      "mechanism": "Classifies assault against an on-duty hospital worker as a felony and sets the maximum incarceration time at three years.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C46",
      "effect": "advances",
      "direction": null,
      "quote": "Assault on an on-duty hospital worker is a felony",
      "mechanism": "Upgrades the offense to a felony, which expands prosecutors' charging options and exposes defendants to greater potential detention.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law sets the maximum penalty for assault at one year in jail. The measure creates a specific felony offense for assaulting an on-duty hospital worker, raising the maximum penalty to three years in prison.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Direct costs include higher state expenditures for incarcerating individuals in state prisons for up to three years, rather than in county jails for up to one year. Opportunity costs include the lost labor and economic output of those serving longer sentences.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "On-duty hospital workers benefit from any deterrence or incapacitation the increased penalty provides. Taxpayers bear the financial cost of longer prison sentences. Individuals convicted of the offense bear the burden of extended incarceration and the lifelong consequences of a felony record.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Prosecutors may use the threat of a three-year felony charge to negotiate plea deals. Potential offenders might be deterred by the harsher penalty, although impulsive acts of violence are often less sensitive to changes in statutory maximums.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses violence against hospital workers. The mechanism increases the maximum criminal penalty for such assaults, which relies on the deterrence and incapacitation effects of longer prison sentences to reduce future incidents.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Prosecutors gain significant discretion, as they acquire the ability to charge a more severe felony offense or use it as leverage during plea bargaining when an assault involves a hospital worker.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "Researchers disagree on the deterrent effect of increasing maximum statutory sentences. Some studies find that longer sentences reduce crime through incapacitation and deterrence, while others find that the severity of punishment has little to no deterrent effect compared to the certainty of apprehension, and that longer sentences primarily increase incarceration costs without proportional safety benefits.",
      "disputed": true
    },
    {
      "clause_id": "§1",
      "question_id": "Q8",
      "answer": "Administration and enforcement will be handled by the existing criminal justice system. Additional resources will be consumed by state prisons holding individuals for up to three years instead of local jails holding them for up to one year.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q9",
      "answer": "As a standard criminal statute, this measure can be repealed or amended by a simple majority vote of the legislature.",
      "disputed": false
    }
  ],
